// op: get | update | delete | block. Guests are never notified (sendUpdates=none): the app never sends.
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string' && body.request_id.length <= 100) ? body.request_id : undefined;
const fail = (code, message, status_code = 400) => [{ json: { valid: false, status_code, error: { code, message }, request_id } }];
const isIso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());
const BASE = 'https://www.googleapis.com/calendar/v3/calendars/primary/events';
const op = body.op;
if (!['get', 'update', 'delete', 'block'].includes(op)) return fail('VALIDATION_ERROR', 'op must be get, update, delete or block');
const idOk = (id) => typeof id === 'string' && /^[A-Za-z0-9_-]{1,1024}$/.test(id);

if (op === 'block') {
  const { title, startsAt, endsAt } = body;
  if (typeof title !== 'string' || title.trim() === '' || title.length > 200) return fail('VALIDATION_ERROR', 'title must be 1-200 characters');
  if (!isIso(startsAt) || !isIso(endsAt)) return fail('VALIDATION_ERROR', 'startsAt and endsAt must be ISO 8601');
  if (new Date(endsAt) <= new Date(startsAt)) return fail('VALIDATION_ERROR', 'endsAt must be after startsAt');
  const description = typeof body.description === 'string' ? body.description.slice(0, 2000) : undefined;
  return [{ json: { valid: true, op, request_id, hasBody: true, req: { method: 'POST', url: BASE + '?sendUpdates=none', body: {
    summary: title.trim(), description, start: { dateTime: startsAt }, end: { dateTime: endsAt }, transparency: 'opaque',
    extendedProperties: { private: { jstackProtected: 'true', jstackSource: 'dashboard' } } } } } }];
}
if (!idOk(body.eventId)) return fail('VALIDATION_ERROR', 'eventId is required');
const url = BASE + '/' + encodeURIComponent(body.eventId);
if (op === 'get') return [{ json: { valid: true, op, request_id, eventId: body.eventId, hasBody: false, req: { method: 'GET', url } } }];
if (op === 'delete') return [{ json: { valid: true, op, request_id, eventId: body.eventId, hasBody: false, req: { method: 'DELETE', url: url + '?sendUpdates=none' } } }];

const p = body.patch;
if (p == null || typeof p !== 'object' || Array.isArray(p)) return fail('VALIDATION_ERROR', 'patch must be an object');
const out = {};
if ('title' in p) { if (typeof p.title !== 'string' || p.title.trim() === '' || p.title.length > 200) return fail('VALIDATION_ERROR', 'title must be 1-200 characters'); out.summary = p.title.trim(); }
if ('startsAt' in p) { if (!isIso(p.startsAt)) return fail('VALIDATION_ERROR', 'startsAt must be ISO 8601'); out.start = { dateTime: p.startsAt }; }
if ('endsAt' in p) { if (!isIso(p.endsAt)) return fail('VALIDATION_ERROR', 'endsAt must be ISO 8601'); out.end = { dateTime: p.endsAt }; }
if (out.start && out.end && new Date(p.endsAt) <= new Date(p.startsAt)) return fail('VALIDATION_ERROR', 'endsAt must be after startsAt');
if ('location' in p) { if (p.location !== null && typeof p.location !== 'string') return fail('VALIDATION_ERROR', 'location must be text'); out.location = p.location || ''; }
if ('description' in p) { if (p.description !== null && typeof p.description !== 'string') return fail('VALIDATION_ERROR', 'description must be text'); out.description = (p.description || '').slice(0, 8000); }
if (Object.keys(out).length === 0) return fail('VALIDATION_ERROR', 'nothing to update');
return [{ json: { valid: true, op, request_id, eventId: body.eventId, hasBody: true, req: { method: 'PATCH', url: url + '?sendUpdates=none', body: out } } }];

const pick = (t) => (t && (t.dateTime || t.date)) || null;
function mapEvent(e) {
  const video = (e.conferenceData && Array.isArray(e.conferenceData.entryPoints)) ? e.conferenceData.entryPoints.find((p) => p.entryPointType === 'video') : undefined;
  const priv = (e.extendedProperties && e.extendedProperties.private) || {};
  return {
    id: e.id, title: e.summary || '(no title)', start: pick(e.start), end: pick(e.end),
    allDay: !!(e.start && e.start.date && !e.start.dateTime), timeZone: (e.start && e.start.timeZone) || null,
    location: e.location || null, meet_link: e.hangoutLink || (video && video.uri) || null, htmlLink: e.htmlLink || null,
    attendees_count: Array.isArray(e.attendees) ? e.attendees.length : 0, transparency: e.transparency || 'opaque',
    eventType: e.eventType || 'default', recurringEventId: e.recurringEventId || null, updated: e.updated || null,
    protectedByEa: priv.jstackProtected === 'true', calendarId: 'primary'
  };
}
const v = $('Validate Input').first().json;
const r = $input.first().json || {};
const sc = r.statusCode;
const err = (code, message, status_code) => [{ json: { ok: false, status_code, request_id: v.request_id, error: { code, message } } }];
const detail = () => JSON.stringify((r.body && r.body.error) || r.body || '').slice(0, 300);
if (sc === 404 || sc === 410) return err('NOT_FOUND', 'event not found', 404);
if (sc === 400) return err('VALIDATION_ERROR', 'Google refused the change: ' + detail(), 422);
if (!(sc >= 200 && sc < 300)) return err('UPSTREAM_ERROR', 'Google answered ' + sc + ': ' + detail(), 502);
const data = v.op === 'delete' ? { deleted: true, id: v.eventId } : { event: mapEvent(r.body || {}) };
return [{ json: { ok: true, response: { ok: true, request_id: v.request_id, data } } }];
